namespace {
void need(bool ok,const char* why){if(!ok)throw std::runtime_error(why);}
void set(SpaceInfinityProcessor& p,const juce::String& id,float value){auto* a=p.state.getParameter(id);need(a!=nullptr,"assignment parameter exists");a->setValueNotifyingHost(a->convertTo0to1(value));}
float get(SpaceInfinityProcessor& p,const juce::String& id){return p.state.getRawParameterValue(id)->load();}
juce::Component* named(juce::Component& c,const juce::String& name){if(c.getName()==name)return &c;for(auto* child:c.getChildren())if(auto* found=named(*child,name))return found;return nullptr;}
ModSlider* slider(juce::Component& c,const juce::String& id){if(c.getProperties()["modParam"].toString()==id)return dynamic_cast<ModSlider*>(&c);for(auto* child:c.getChildren())if(auto* found=slider(*child,id))return found;return nullptr;}
juce::MouseEvent mouse(juce::Component& c,juce::Point<float> at,juce::Point<float> start,int flags=juce::ModifierKeys::leftButtonModifier,bool dragged=false){return {juce::Desktop::getInstance().getMainMouseSource(),at,juce::ModifierKeys(flags),1,0,0,0,0,&c,&c,juce::Time::getCurrentTime(),start,juce::Time::getCurrentTime(),1,dragged};}
void ringDrag(ModSlider& knob,int pixels,bool fine=false){auto r=knob.getLocalBounds().toFloat();if(knob.getTextBoxPosition()==juce::Slider::TextBoxBelow)r.removeFromBottom(float(knob.getTextBoxHeight()));const float radius=juce::jmin(43.0f,juce::jmin(r.getWidth(),r.getHeight())*.44f)*1.13f;auto at=r.getCentre().getPointOnCircumference(radius,0),to=at.translated(0,float(-pixels));int flags=juce::ModifierKeys::leftButtonModifier|(fine?juce::ModifierKeys::shiftModifier:0);knob.mouseDown(mouse(knob,at,at,flags));knob.mouseDrag(mouse(knob,to,at,flags,true));knob.mouseUp(mouse(knob,to,at,flags,true));}
int changed(const juce::Image& a,const juce::Image& b){int n=0;for(int y=0;y<a.getHeight();++y)for(int x=0;x<a.getWidth();++x)if(a.getPixelAt(x,y)!=b.getPixelAt(x,y))++n;return n;}
double energy(SpaceInfinityProcessor& p){p.prepareToPlay(48000,128);juce::AudioBuffer<float> b(2,128);double e=0;for(int n=0;n<150;++n){juce::MidiBuffer m;if(n==0)m.addEvent(juce::MidiMessage::noteOn(1,60,.8f),0);p.processBlock(b,m);if(n>80)for(int i=0;i<128;++i){float v=b.getSample(0,i);need(std::isfinite(v),"finite envelope modulation");e+=v*v;}}return e;}
}
int runModulationWorkflowSmoke(){try{
 auto p=std::make_unique<SpaceInfinityProcessor>();p->loadPreset(0);auto editor=std::unique_ptr<juce::AudioProcessorEditor>(p->createEditor());editor->setSize(1000,790);
 const auto page=[&](const juce::String& title){for(auto* c:editor->getChildren())if(auto* button=dynamic_cast<juce::TextButton*>(c))if(button->getButtonText()==title){button->onClick();return;}throw std::runtime_error("page button missing");};
 auto* filterBadge=named(*editor,"Modulation depth "+p->macroTargets()[1]);need(filterBadge&&filterBadge->isVisible(),"main filter assignment badge present");
 for(const auto* title:{"FX","GATE","SEQ"}){page(title);need(!filterBadge->isVisible(),"filter badge hides on other pages");}
 page("MAIN");need(filterBadge->isVisible(),"filter badge returns on MAIN");page("ENGINES");need(!filterBadge->isVisible(),"filter badge hides immediately behind engine menu");
 auto* engineMenu=juce::Component::getCurrentlyModalComponent();need(engineMenu!=nullptr,"engine menu opened");engineMenu->exitModalState(0);engineMenu->setVisible(false);page("MAIN");need(filterBadge->isVisible(),"filter badge restores after closing the menu");
 auto* source=dynamic_cast<ModSourceButton*>(named(*editor,"Amp envelope modulation source"));auto* cutoff=slider(*editor,"cutoff");need(source&&cutoff,"draggable amp source and destination");const float base=get(*p,"cutoff");
 const juce::DragAndDropTarget::SourceDetails amp("INFINITY:ENV:0",source,{}),lfo0("INFINITY:LFO:0",source,{}),lfo1("INFINITY:LFO:1",source,{});
 need(cutoff->isInterestedInDragSource(amp),"knob accepts envelope drag");cutoff->itemDropped(amp);const auto ampDepth=p->modulationDepthFor("INFINITY:ENV:0","cutoff");need(ampDepth.isNotEmpty(),"amp drag creates route");cutoff->itemDropped(lfo0);cutoff->itemDropped(lfo1);need(juce::Component::getCurrentlyModalComponent()==nullptr,"drop assigns without forcing popup");const auto first=p->modulationDepthFor("INFINITY:LFO:0","cutoff"),second=p->modulationDepthFor("INFINITY:LFO:1","cutoff");set(*p,first,.12f);set(*p,second,.23f);set(*p,ampDepth,.2f);ringDrag(*cutoff,16);need(std::abs(get(*p,second)-.33f)<.0001&&get(*p,"cutoff")==base&&std::abs(get(*p,first)-.12f)<.0001,"ring edits selected LFO amount only");
 source->mouseDown(mouse(*source,{5,5},{5,5}));static_cast<juce::Component*>(source)->mouseUp(mouse(*source,{5,5},{5,5}));ringDrag(*cutoff,16,true);need(std::abs(get(*p,ampDepth)-.21f)<.0001&&get(*p,"cutoff")==base,"amp source selection and fine amount drag");{auto center=cutoff->getLocalBounds().toFloat().getCentre();auto to=center.translated(0,-16);const int alt=juce::ModifierKeys::leftButtonModifier|juce::ModifierKeys::altModifier;const float start=get(*p,ampDepth);cutoff->mouseDown(mouse(*cutoff,center,center,alt));cutoff->mouseDrag(mouse(*cutoff,to,center,alt,true));cutoff->mouseUp(mouse(*cutoff,to,center,alt,true));need(std::abs(get(*p,ampDepth)-start-.1f)<.0001&&get(*p,"cutoff")==base,"Serum-style Alt-drag edits amount only");const int shiftAlt=alt|juce::ModifierKeys::shiftModifier;cutoff->mouseDown(mouse(*cutoff,center,center,shiftAlt));cutoff->mouseUp(mouse(*cutoff,center,center,shiftAlt));need(get(*p,SpaceInfinityProcessor::modulationPolarityId(7,0,true))==2,"Shift-Alt-click toggles bidirectional modulation");}
 ringDrag(*cutoff,-100);need(get(*p,ampDepth)<0&&get(*p,"cutoff")==base,"negative amount without changing base value");cutoff->showAmount(ampDepth,"Amp envelope -> Cutoff");auto* amount=dynamic_cast<juce::Slider*>(named(*editor,"Modulation amount"));need(amount!=nullptr,"editable numeric amount");amount->setValue(-.35,juce::sendNotificationSync);need(std::abs(get(*p,ampDepth)+.35f)<.0001&&get(*p,"cutoff")==base,"numeric amount edits selected route");if(auto* modal=juce::Component::getCurrentlyModalComponent())modal->exitModalState(0);
 for(bool ampEnv:{true,false}){auto* view=dynamic_cast<EnvelopeView*>(named(*editor,ampEnv?"Amp envelope graph":"Filter envelope graph"));need(view!=nullptr,"live envelope graph");auto* hold=slider(*editor,ampEnv?"ampHold":"filterHold");auto* decay=slider(*editor,ampEnv?"ampDecay":"filterDecay");need(hold&&decay,"actual hold/decay knobs");set(*p,ampEnv?"ampSustain":"filterSustain",.25f);hold->setValue(.02,juce::sendNotificationSync);decay->setValue(.08,juce::sendNotificationSync);auto before=view->createComponentSnapshot(view->plotBounds().toNearestInt());hold->setValue(.4,juce::sendNotificationSync);auto after=view->createComponentSnapshot(view->plotBounds().toNearestInt());need(changed(before,after)>20,"hold knob reshapes plotted curve, beyond numeric row");before=after;decay->setValue(.8,juce::sendNotificationSync);after=view->createComponentSnapshot(view->plotBounds().toNearestInt());need(changed(before,after)>20,"decay knob reshapes plotted curve");set(*p,ampEnv?"ampSustain":"filterSustain",1);before=view->createComponentSnapshot(view->plotBounds().toNearestInt());hold->setValue(.8,juce::sendNotificationSync);after=view->createComponentSnapshot(view->plotBounds().toNearestInt());need(changed(before,after)>10,"hold remains visible at full sustain");}
 auto* graph=dynamic_cast<CurveEditor*>(named(*editor,"LFO 1 curve"));need(graph!=nullptr,"LFO curve display");p->enableLfoCurve(0);set(*p,p->lfoParameterId(0,"CurveCount"),5);const float xs[]{0,.1f,.3f,.6f,1},ys[]{0,1,1,.2f,.2f};for(int n=0;n<5;++n){set(*p,p->lfoParameterId(0,"X")+juce::String(n),xs[n]);set(*p,p->lfoParameterId(0,"Y")+juce::String(n),ys[n]);set(*p,p->lfoParameterId(0,"Bend")+juce::String(n),0);}auto r=graph->plotBounds();auto at=juce::Point<float>(r.getX()+r.getWidth()*.3f,r.getY()),to=juce::Point<float>(r.getX()+r.getWidth()*.5f,r.getY());graph->mouseDown(mouse(*graph,at,at));graph->mouseDrag(mouse(*graph,to,at,juce::ModifierKeys::leftButtonModifier,true));graph->mouseUp(mouse(*graph,to,at));need(std::abs(p->lfoCurveValue(0,.4)-1)<.0001,"LFO hold drag changes real curve");at={r.getX()+r.getWidth()*.6f,r.getBottom()-r.getHeight()*.2f};to={r.getX()+r.getWidth()*.8f,at.y};graph->mouseDown(mouse(*graph,at,at));graph->mouseDrag(mouse(*graph,to,at,juce::ModifierKeys::leftButtonModifier,true));graph->mouseUp(mouse(*graph,to,at));need(p->lfoCurveValue(0,.7)>.3f,"LFO decay drag changes real curve");editor.reset();
 auto routes=std::make_unique<SpaceInfinityProcessor>();routes->loadPreset(0);routes->assignFlexibleSource(0,3,routes->flexibleTargetIndex("cutoff"));std::set<int> indexes;for(int s=0;s<10;++s)for(int n=0;n<16;++n)need(indexes.insert(SpaceInfinityProcessor::flexibleRouteIndex(s,n)).second,"route slots never collide");const char* targets[]{"osc1Gain","osc2Gain","osc1Detune","osc2Detune","osc1Pan","osc2Pan","subPan","noisePan","subLevel","filterEnvAmount","filterDecay","filterHold","filterAttack","filterRelease","filterSustain","chorusDepth"};for(auto id:targets)need(routes->dropModulation("INFINITY:ENV:0",id),"amp supports sixteen generic assignments");need(!routes->dropModulation("INFINITY:ENV:0","phaserRate"),"full amp routes reject without overwriting");need(routes->flexibleSourceTarget(0,3)==routes->flexibleTargetIndex("cutoff"),"amp route expansion preserves existing macro slot");juce::MemoryBlock saved;routes->getStateInformation(saved);auto restored=std::make_unique<SpaceInfinityProcessor>();restored->setStateInformation(saved.getData(),int(saved.getSize()));for(int n=0;n<16;++n)need(restored->flexibleSourceTarget(9,n)==routes->flexibleSourceTarget(9,n),"all amp routes recall");
 auto signal=std::make_unique<SpaceInfinityProcessor>();signal->loadPreset(0);for(auto id:{"compEnabled","delayEnabled","reverbEnabled","chorusEnabled","flangerEnabled","phaserEnabled","gateEnabled","pumpEnabled","eqEnabled","convolverEnabled","distEnabled","osc2Enabled"})set(*signal,id,0);set(*signal,"gain",.2f);set(*signal,"noiseLevel",0);set(*signal,"subLevel",0);set(*signal,"routeA",0);set(*signal,"osc1PhaseReset",1);set(*signal,"attack",0);set(*signal,"ampSustain",1);set(*signal,"osc1Gain",-12);const auto dry=energy(*signal);need(signal->dropModulation("INFINITY:ENV:0","osc1Gain"),"amp routes to oscillator gain");auto depth=signal->modulationDepthFor("INFINITY:ENV:0","osc1Gain");set(*signal,depth,.08f);const auto loud=energy(*signal);set(*signal,depth,-.08f);const auto quiet=energy(*signal);need(loud>dry*2&&quiet<dry*.5,"signed generic amp amount changes actual audio");
 set(*signal,"ampDecay",.02f);set(*signal,"ampSustain",.5f);set(*signal,depth,0);const auto centred=energy(*signal);set(*signal,SpaceInfinityProcessor::modulationPolarityId(9,0),1);set(*signal,depth,.08f);const auto bipolarEnergy=energy(*signal);need(std::abs(bipolarEnergy/centred-1)<.02,"bidirectional amp modulation centres at half envelope level");
 std::cout<<"Modulation workflow: amp/LFO drag assignment, selected ring/fine/numeric amounts, base isolation, live hold/decay, LFO edits, 16-slot recall and actual amp audio passed\n";return 0;
}catch(const std::exception& e){std::cerr<<"Modulation workflow: "<<e.what()<<'\n';return 182;}}
